def qualification_inputs() -> dict:
    raw = zlib.decompress(base64.b64decode(_PACKET_ZLIB_B64))
    if "sha256:" + hashlib.sha256(raw).hexdigest() != PACKET_SHA256:
        raise RuntimeError("pinned 000422 qualification packet hash differs")
    packet = json.loads(raw)
    inputs = packet.get("assessorInputs")
    if not isinstance(inputs, dict):
        raise RuntimeError("pinned 000422 qualification packet lacks assessorInputs")
    return copy.deepcopy(inputs)
